"""
Collect form answers from a FlexContainer recursively.

Traverses all children of the given container, collecting
custom.item from each component and instances from Flex Repeaters.
Appends insights metadata as last item.

Version: 1.0.0

Args:
	flexContainer (Component): The FlexContainerGroup to traverse

Returns:
	dict: {"items": [{papoItemID, registerTypeID, answer}, ...]}

Changelog:
	2026-07-05 | William | v1.0.0 - Initial version, standardized across all forms
"""

def _appendItem(candidate, outList):
	"""Append a valid item dict to the output list."""
	if not candidate:
		return
	try:
		outList.append({
			"papoItemID": candidate.get("papoItemID"),
			"registerTypeID": candidate.get("registerTypeID"),
			"answer": candidate.get("answer")
		})
	except Exception:
		pass


def _gatherFromInstances(component):
	"""Extract items from Flex Repeater props.instances."""
	items = []
	try:
		if hasattr(component, "props") and hasattr(component.props, "instances"):
			for inst in component.props.instances:
				candidate = None
				if hasattr(inst, "get"):
					candidate = inst.get("item", None)
					if candidate is None:
						vp = inst.get("viewParams", None)
						if hasattr(vp, "get"):
							candidate = vp.get("item", None)

				if candidate is not None:
					if isinstance(candidate, (list, tuple)):
						for it in candidate:
							_appendItem(it, items)
					else:
						_appendItem(candidate, items)
	except Exception:
		pass
	return items


def gatherItems(component):
	"""Recursively collect custom.item from component tree."""
	items = []

	# Collect custom.item from current component
	try:
		if hasattr(component, "custom") and hasattr(component.custom, "item"):
			_appendItem(component.custom.item, items)
	except Exception:
		pass

	# Collect from Flex Repeater instances (skip children to avoid duplicates)
	if hasattr(component, "props") and hasattr(component.props, "instances"):
		items.extend(_gatherFromInstances(component))
		return items

	# Recurse into children
	try:
		for child in component.getChildren():
			items.extend(gatherItems(child))
	except Exception:
		pass

	return items


# Collect all items from the container
allItems = gatherItems(flexContainer)

# Append insights metadata as last item
insightText = getattr(self.view.custom, "insights", None)
registerType = getattr(self.view.custom, "registerTypeID", None)
user = getattr(self.view.custom, "user", None)
now = system.date.now()

if insightText is not None:
	allItems.append({
		"user": user,
		"timestamp": str(now),
		"insights": insightText,
		"registerTypeID": registerType
	})

return {"items": allItems}
